from ui_incremental import *
record(T+'ControlCenterWriteSafetyTests.cs','Fake-HTTP tests for retained business-day writes.',[
 ('Handler(', 'Delegates all requests to fixture, no live database. Json wraps actual response body/status; cancellation token not asserted.'),
 ('Unknown_management_day_write_retains_its_exact_request_until_confirmation(', 'Five action theory drives open/close/reopen/checklist/exception on one VM. First HTTP throws, next422, third succeeds; asserts exact path+body replay, pending global state, frozen edit, close refusal and final cleanup. Read fixture updates status/existence only final attempt; does not simulate actual committed server before loss.'),
 ('Unknown_day_history_disables_open_close_and_reopen(', '503 reads keep all day mutations disabled and load error visible. Does not exercise stale successful read after changing account or process recovery.')
 ],'SOURCE_REVIEW_ONLY, NOT_EXECUTED. Valid same-process immutable retry assertions. Missing fresh-process recovered DTO context, journal corruption, session change, mid-flight root navigation and native focus tests.','Add restart reconstruction and session identity tests; preserve actual backend transactional coverage separately.')
record(T+'ManagementWriteSafetyTests.cs','One-process fake-HTTP regression suite for management financial operations.',[
 ('Handler(', 'Fixture delegate ignores cancellation, Json/Dto helpers use Web serialization and synthetic DTOs.'),
 ('CreateFlowAsync(', 'Builds11 operation adapters: delivery assign/outcome/settle, payroll create/pay, employee advance, individual inventory count/waste, supplier/create receipt/pay. CorruptInputs deliberately edits live fields after ambiguity. This does not include batch count sheet or shift management, so those risks are not contradicted.'),
 ('Lost_response_then_rejection_keeps_the_exact_write_and_blocks_abandonment(', 'First lost response,422 then success; equality of all3 path/body pairs proves current-VM snapshot reuse. Checks pending session, edit lock, close prevention and cleanup; settle remains account screen until explicit close. Does not persist/reconstruct VM.'),
 ('Lost_payroll_transition_reconciles_committed_status_without_advancing_a_second_step(', 'Keeps original run despite selection attempt; second transition422 plus read calculated releases pending without next status step. First reconciliation read503 keeps unknown. Demonstrates live context recovery only; UI017 fresh-process context deadlock still uncovered.')
 ],'SOURCE_REVIEW_ONLY, NOT_EXECUTED. No real payments/stock/customer records. Missing restart/payroll and batch-sheet workflows, delayed callbacks, cross-user journal and native command gating.','Extend tests using clean per-test durable store, new VM after commit/loss, and exact global navigation lifecycle.')
record(T+'NativeScreenLayoutProbe.cs','Opt-in native view-construction probe, not business workflow test.',[
 ('Start(', 'Replaces window content with white host; reflection selects non-placeholder Views UserControls, constructs without session/DataContext at6 nominal size/scale combinations, resizes actual window and waits25ms. Writes progress/results then closes. Scope cannot establish populated modal/binding/auth/API correctness or pixel contrast. Must not run against active user draft.'),
 ('CountVisuals(', 'Recursively counts current visual descendants; count alone not overflow/accessibility/contrast assertion. Loaded callback guarded once; per-view exceptions become report data; finally output/close may itself throw. Management probe gated CASHIER_LAYOUT_PROBE.')
 ],'SOURCE_REVIEW_ONLY, NOT_EXECUTED. Simulated DIP sizes are not OS DPI changes; errors captured need consuming verifier. No screenshots implied.','Use isolated process and populated states for layout; assert geometry/theme/automation independently. Do not count construction as full usability evidence.')
record(T+'NativeManagementLayoutProbe.cs','Opt-in populated attendance/user-dialog native geometry fixture.',[
 ('FixtureHandler', 'Throws any nonGET; users/all returns synthetic owner and all otherGET permission list. No real authentication or mutation.'),
 ('RunAsync(', 'Runs4 states at6 nominal sizes. Uses real VM constructors/dialog commands and long Arabic names/errors, attaches real views. Measures named card/scroll/footer and asserts positive geometry,44px footer/scroll, card viewport bounds and footer separation. Each exception captured in returned record rather than thrown to top runner. Covers only attendance correction and user create.'),
 ('Bounds(', 'TransformToVisual reports layout rectangle in parent DIP coordinates. No keyboard focus, scroll reach, text clipping, native DPI or dark theme pixel validation.')
 ],'SOURCE_REVIEW_ONLY, NOT_EXECUTED. Synthetic owner all-permission hides role-specific behavior; no source says real user setup validated.','Keep opt-in probe isolated and treat returned error fields as failures; broaden independently justified modal cases after authorization.')
record(T+'UserWorkflowTests.cs','Synthetic HTTP user-management immutability, privilege display and PIN retry tests.',[
 ('Handler(', 'Session fixture routesGET to synthetic users/permissions and nonGET to callback. Json creates actual DTO-shaped body, not real token-bearing auth session.'),
 ('User_creation_retains_the_original_identity_pin_and_permissions_after_lost_confirmation(', 'Edits fields after first lost response; compares3 identical serialized creates across422/success, blocks selection/close, clears PIN after success. Never constructs new VM or reads real secrets.'),
 ('Existing_user_writes_retry_the_original_decision_and_target(', 'Theory permission/active changes retain target/decision with2 identical bodies and blocked switch/create; fake200 confirms.'),
 ('Lost_self_pin_confirmation_is_reconciled_to_the_same_user_without_rewriting_the_pin(', 'Proof endpoint returns UserSummaryDto without access token. Asserts one write and one proof, cleared fields and current user unchanged. Therefore does not exercise token replacement in real AuthSessionResponse path.'),
 ('A_pin_proof_for_a_different_user_does_not_confirm_the_pending_change(', 'Wrong-ID proof remains pending and retries original body; CurrentUser unchanged asserted. Bearer Authorization header not asserted, and proof response lacks token, leaving UI020 real token mutation uncovered.'),
 ('Administrative_pin_reset_cannot_target_the_owner_and_creation_cannot_grant_unheld_permissions(', 'Manager users_manage/pos blocked owner PIN reset and new all permission; zero fixture writes verifies client gating. Does not establish server authorization or TOCTOU account change checks.')
 ],'SOURCE_REVIEW_ONLY, NOT_EXECUTED. PIN strings are fixture literals, no actual credential report. Missing token-bearing proof, fresh-session pending request, secure journal storage and concurrent account switch.','Add real authentication response shape/header assertions and restart context tests; independently server-enforce all privilege rules.')
